// The static `Imposter()` extensions are only generated by the Roslyn 4.14+ builds of the generator.
#if ROSLYN4_14_OR_GREATER
using System.Threading.Tasks;
using Imposter.CodeGenerator.Tests.Helpers;
using Microsoft.CodeAnalysis.CSharp;
using Xunit;

namespace Imposter.CodeGenerator.Tests.Features.NamingCollisionPrevention;

// Each target gets a static class for its Imposter() extensions, named after the target. Same-named targets of
// different arity in one namespace keep their extension classes apart.
public class ImposterExtensionsClassNameCollisionTests
{
    [Fact]
    public async Task GivenGenericAndNonGenericInterfacesOfTheSameName_WhenImposterExtensionsAreUsed_ShouldCompile()
    {
        await AssertCompiles(
            "[assembly: GenerateImposter(typeof(Sample.IFoo))] [assembly: GenerateImposter(typeof(Sample.IFoo<>))]",
            "public interface IFoo { int Get(); } public interface IFoo<T> { T Get(); }",
            "Sample.IFoo.Imposter().Instance().Get(); Sample.IFoo<int>.Imposter().Instance().Get();"
        );
    }

    [Fact]
    public async Task GivenGenericInterfacesOfTheSameNameAndDifferentArity_WhenImposterExtensionsAreUsed_ShouldCompile()
    {
        await AssertCompiles(
            "[assembly: GenerateImposter(typeof(Sample.IFoo<>))] [assembly: GenerateImposter(typeof(Sample.IFoo<,>))]",
            "public interface IFoo<T> { T Get(); } public interface IFoo<T, U> { U Get(T key); }",
            "Sample.IFoo<int>.Imposter().Instance().Get(); Sample.IFoo<int, string>.Imposter().Instance().Get(1);"
        );
    }

    [Fact]
    public async Task GivenAnotherTargetNamedWithTheArity_WhenImposterExtensionsAreUsed_ShouldCompile()
    {
        await AssertCompiles(
            "[assembly: GenerateImposter(typeof(Sample.IFoo))] [assembly: GenerateImposter(typeof(Sample.IFoo<>))] [assembly: GenerateImposter(typeof(Sample.IFoo1))]",
            "public interface IFoo { int Get(); } public interface IFoo<T> { T Get(); } public interface IFoo1 { int Get(); }",
            "Sample.IFoo.Imposter().Instance().Get(); Sample.IFoo<int>.Imposter().Instance().Get(); Sample.IFoo1.Imposter().Instance().Get();"
        );
    }

    [Fact]
    public async Task GivenGenericAndNonGenericClassesOfTheSameName_WhenImpostersAreGenerated_ShouldCompile()
    {
        await AssertCompiles(
            "[assembly: GenerateImposter(typeof(Sample.Foo))] [assembly: GenerateImposter(typeof(Sample.Foo<>))]",
            "public class Foo { public virtual int Get() => 0; } public class Foo<T> { public virtual T Get() => default!; }",
            "new Sample.FooImposter().Instance().Get(); new Sample.FooImposter<int>().Instance().Get();"
        );
    }

    private static async Task AssertCompiles(string registrations, string targets, string usage)
    {
        var context = await GeneratorTestHelper.CreateContext(
            /*lang=csharp*/
            $$"""
            using Imposter.Abstractions;

            {{registrations}}

            namespace Sample
            {
                {{targets}}
            }
            """,
            baseSourceFileName: "SameNamedTargets.cs",
            snippetFileName: "Snippet.cs",
            assemblyName: nameof(ImposterExtensionsClassNameCollisionTests),
            LanguageVersion.Preview
        );

        GeneratorTestHelper.AssertNoDiagnostics(
            context.CompileSnippet(
                /*lang=csharp*/
                $$"""
                using Imposter.Abstractions;
                using Sample;

                public static class Usage
                {
                    public static void Run()
                    {
                        {{usage}}
                    }
                }
                """
            )
        );
    }
}
#endif
